{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE REDTAPE_DB.MAPLEMONK.STATUS_STOCK_REPORT AS WITH BASE AS ( SELECT STOCK_STATUS_REP.LOCATION, RIGHT(STOCK_STATUS_REP.SKU, LENGTH(STOCK_STATUS_REP.SKU) - 1) AS SKU, STOCK_STATUS_REP.EAN, STOCK_STATUS_REP.CATEGORY, CASE WHEN STOCK_STATUS_REP.GENDER = \'UNISEX\' THEN \'MEN\' WHEN STOCK_STATUS_REP.GENDER = \'KIDS-UNISEX\' THEN \'KIDS\' ELSE STOCK_STATUS_REP.GENDER END AS \"GENDER\", STOCK_STATUS_REP.SUB_CATEGORY, STOCK_STATUS_REP.\"Available Quantity\" AS AVAILABLE_QUANTITY, RIGHT( LEFT( STOCK_STATUS_REP.SKU, CHARINDEX(\'-\', STOCK_STATUS_REP.SKU) - 1 ), LENGTH( LEFT( STOCK_STATUS_REP.SKU, CHARINDEX(\'-\', STOCK_STATUS_REP.SKU) - 1 ) ) -1 ) AS ARTICLE, STOCK_STATUS_REP.\"Reserved (Picked)\" AS RES_PICKED, STOCK_STATUS_REP.\"Reserved (Not Picked)\" AS RES_N_PICKED, STOCK_STATUS_REP.\"Sold (Pending Manifest)\" AS SOLD_PENDING_MANIFEST, STOCK_STATUS_REP.\"Available Quantity (Bin Locked)\" AS AV_QTY_BIN_LOCKED, FROM EASYECOM_STATUS_STOCK_REPORTS STOCK_STATUS_REP ), ENRICHED AS ( SELECT BASE.LOCATION, BASE.SKU, BASE.EAN, BASE.CATEGORY, BASE.ARTICLE, BASE.GENDER, BASE.SUB_CATEGORY, BASE.AVAILABLE_QUANTITY, CATE_ABC.\"Category A,B,C\" AS CATEGORY_ABC, CASE WHEN REGEXP_LIKE(RIGHT(BASE.ARTICLE, 1), \'[A-Z]\') THEN LEFT(BASE.ARTICLE, LEN(BASE.ARTICLE) - 1) ELSE BASE.ARTICLE END AS STYLE FROM BASE INNER JOIN EASYECOM_REDTAPE_PRODUCT_MASTER PRODUCT_MASTER ON BASE.SKU = PRODUCT_MASTER.SKU LEFT JOIN PRODUCT_CATEGORYABC_MAPPING CATE_ABC ON BASE.ARTICLE = CATE_ABC.ARTICLE WHERE BASE.CATEGORY = \'01-Footwear\' ), CLEANED AS ( SELECT LOCATION, SKU, EAN, CATEGORY, ARTICLE, STYLE, GENDER, CASE WHEN SUB_CATEGORY LIKE \'Open%\' THEN \'Open\' ELSE SUB_CATEGORY END AS \"Cat (Open/Closed)\", CATEGORY_ABC AS \"Category A,B,C\", CASE WHEN AVAILABLE_QUANTITY - 3 < 0 THEN 0 ELSE AVAILABLE_QUANTITY - 3 END AS STOCK FROM ENRICHED ), PRODUCT_MASTER_CATEGORY_1 AS ( SELECT PRODUCT_MASTER.SKU, CF.VALUE:value::STRING AS CATEGORY_1 FROM EASYECOM_REDTAPE_PRODUCT_MASTER PRODUCT_MASTER, LATERAL FLATTEN(input => PRODUCT_MASTER.\"CUSTOM_FIELDS\") CF WHERE CF.VALUE:field_name::STRING = \'CATEGORY-1\' ), CATEGORY_1_NORMALIZED AS ( SELECT SKU, CASE WHEN UPPER(CATEGORY_1) LIKE \'%ATHLEISURE\' THEN \'ATHLEISURE\' WHEN UPPER(CATEGORY_1) LIKE \'%SANDAL%\' THEN \'SANDALS\' WHEN UPPER(CATEGORY_1) = \'MEN\'\'S SLIDERS\' THEN \'SLIDERS\' WHEN UPPER(CATEGORY_1) LIKE \'%SLIDERS\' THEN \'SANDALS\' WHEN UPPER(CATEGORY_1) LIKE \'%LIFESTYLE\' THEN \'LIFESTYLE\' WHEN UPPER(CATEGORY_1) LIKE \'%CASUALS\' THEN \'CASUALS\' WHEN UPPER(CATEGORY_1) LIKE \'%DRESS SHOES\' THEN \'DRESS SHOES\' WHEN UPPER(CATEGORY_1) LIKE \'%BOOTS\' THEN \'BOOTS\' WHEN UPPER(CATEGORY_1) LIKE \'%WALKING\' THEN \'WALKING\' WHEN UPPER(CATEGORY_1) LIKE \'%FORMAL\' THEN \'FORMAL\' WHEN UPPER(CATEGORY_1) IN (\'FAST SPORTS\', \'DRIFT+\', \'ATHLEISURE\') THEN \'ATHLEISURE\' WHEN UPPER(CATEGORY_1) IN (\'LIFESTYLE\', \'SUPER SNEAKER\') THEN \'LIFESTYLE\' ELSE CATEGORY_1 END AS \"CATEGORY-1\" FROM PRODUCT_MASTER_CATEGORY_1 ) SELECT CLD.LOCATION, CLD.SKU, RIGHT(CLD.EAN, LENGTH(CLD.EAN)-1) AS EAN, CLD.CATEGORY, CLD.ARTICLE, CLD.STYLE, CLD.GENDER, CAT1.\"CATEGORY-1\", CASE WHEN CAT1.\"CATEGORY-1\" IN (\'SANDALS\',\'SANDALS\') THEN \'Open\' ELSE CLD.\"Cat (Open/Closed)\" END AS \"Cat (Open/Closed)\", CLD.STOCK, BASE.RES_PICKED + BASE.RES_N_PICKED + BASE.SOLD_PENDING_MANIFEST + BASE.AV_QTY_BIN_LOCKED AS \"RES+BIN+QC\" FROM CLEANED CLD LEFT JOIN CATEGORY_1_NORMALIZED CAT1 ON CLD.SKU = CAT1.SKU LEFT JOIN BASE BASE ON CLD.SKU = BASE.SKU ORDER BY CLD.STOCK DESC",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            